   "act": "state",
   "guide": "The speaker states the content in their own words.",
   "content": [
    {
     "text": "Archiving. All astronomical data are saved into the Archiving system. Data storage and transport for astronomical data will be in FITS format. On-line access to the archiver will be through STARCAT.",
     "role": "statement"
    }
   ]
  },
